-- auditorias 0001: initial schema (generated by novvus-sdk)

CREATE TABLE audit (
	name VARCHAR(200) NOT NULL, 
	audit_type VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	scope VARCHAR(2000) NOT NULL, 
	start_date DATE, 
	end_date DATE, 
	auditor_id UUID, 
	notes VARCHAR(4000) NOT NULL, 
	owner_user_id UUID, 
	id UUID NOT NULL, 
	org_id UUID NOT NULL, 
	ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
	custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_audit_org_id ON audit (org_id);

ALTER TABLE audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON audit
    USING (org_id = current_setting('app.org_id')::uuid)
    WITH CHECK (org_id = current_setting('app.org_id')::uuid);

CREATE TABLE audit_finding (
	audit_id UUID NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	description VARCHAR(4000) NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	responsible_id UUID, 
	due_date DATE, 
	notes VARCHAR(4000) NOT NULL, 
	id UUID NOT NULL, 
	org_id UUID NOT NULL, 
	ext JSONB DEFAULT '{}'::jsonb NOT NULL, 
	custom JSONB DEFAULT '{}'::jsonb NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	deleted_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(audit_id) REFERENCES audit (id) ON DELETE CASCADE
);

CREATE INDEX ix_audit_finding_org_id ON audit_finding (org_id);

ALTER TABLE audit_finding ENABLE ROW LEVEL SECURITY;
